let num = 42;
let str = "42";
let bool = true;
let empty = null;
let notDefined; // undefined

console.log(typeof num);   // "number"
console.log(typeof str);   // "string"
console.log(typeof bool);  // "boolean"
console.log(typeof empty); // "object" (баг!)
console.log(typeof notDefined); // "undefined"

let a = null;      // Явно ничего
let b = undefined; // Неопределено
let c = 0;         // Числовое значение (не «пусто»)
let d = "";        // Пустая строка (не «пусто»)
let e = false;     // Булево значение (не «пусто»)

// Все они "falsy" (приводятся к false в булевом контексте):
if (!a) console.log("null — falsy");
if (!b) console.log("undefined — falsy");
if (!c) console.log("0 — falsy");
if (!d) console.log("'' — falsy");
if (!e) console.log("false — falsy");

console.log(0.1 + 0.2); // 0.30000000000000004 (не 0.3!)
// Это не баг JavaScript — так работает представление дробных чисел в компьютере.
// Исправляйте через toFixed():
console.log(parseFloat((0.1 + 0.2).toFixed(1))); // 0.3
